public int smallestDistancePair(int[] nums, int k) {
    int n = nums.length;
    int[] dists = new int[n * (n - 1) / 2];
    int idx = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            dists[idx++] = Math.abs(nums[i] - nums[j]);
        }
    }
    Arrays.sort(dists);
    return dists[k - 1];
}

